#include "Chorus.h"
static void testChorus(const File& root,Assets& assets){
    ChorusSettings defaults;expect(validateChorus(defaults).wasOk()&&!defaults.enabled,"chorus defaults are valid and bypassed");
    auto custom=defaults;custom.enabled=true;custom.mix=.63f;custom.rate=1.7f;custom.depth=.81f;custom.delay=23;custom.feedback=-.37f;custom.width=.72f;
    ChorusSettings read;expect(chorusFromJson(chorusToJson(custom),read).wasOk()&&read==custom,"chorus JSON roundtrips every control including signed feedback");
    for(int i=0;i<6;++i){for(double n:{0.,.5,1.}){auto candidate=defaults;auto v=chorusFromNormal(i,n);expect(setChorusValue(candidate,i,v).wasOk()&&std::abs(chorusNormal(i,chorusValue(candidate,i))-n)<.000001,"chorus controls map their full range including logarithmic rate");}auto candidate=custom;expect(setChorusValue(candidate,i,std::numeric_limits<double>::quiet_NaN()).failed()&&candidate==custom,"nonfinite chorus edit preserves prior settings");}
    for(const char* field:{"mix","rate","depth","delay","feedback","width"})for(const var& invalid:{var("bad"),var(-999.),var(999.),var(std::numeric_limits<double>::infinity())}){auto json=chorusToJson(custom);json.getDynamicObject()->setProperty(field,invalid);auto before=read;expect(chorusFromJson(json,read).failed()&&read==before,"invalid chorus JSON fails atomically");}
    auto missing=chorusToJson(custom);missing.getDynamicObject()->removeProperty("width");expect(chorusFromJson(missing,read).failed()&&read==custom,"incomplete chorus state is rejected");missing=chorusToJson(custom);missing.getDynamicObject()->setProperty("enabled",1);expect(chorusFromJson(missing,read).failed(),"chorus enabled flag requires a boolean");
    // A warmed, unmodulated wet-only delay has an independently known impulse response.
    for(double rate:{8000.,22050.,44100.,48000.,96000.,192000.}){
        StereoChorus fx;fx.prepare(rate);auto p=defaults;p.enabled=true;p.mix=1;p.depth=0;p.delay=10;p.feedback=0;fx.setSettings(p);float l=0,rr=0;for(int i=0;i<(int)(rate*.3);++i){l=rr=0;fx.process(l,rr);}
        double delay=rate*.01;int first=(int)std::floor(delay);double fraction=delay-first;bool impulse=true;
        for(int i=0;i<first+3;++i){l=i==0?.4f:0;rr=i==0?-.2f:0;fx.process(l,rr);double weight=i==first?1-fraction:i==first+1?fraction:0;impulse&=std::abs(l-.4*weight)<.000002&&std::abs(rr+.2*weight)<.000002;}
        expect(impulse,"wet-only chorus matches exact fractional-delay stereo impulse at each supported rate");
    }
    StereoChorus cold;cold.prepare(48000);auto coldSettings=defaults;coldSettings.enabled=true;coldSettings.mix=1;coldSettings.depth=0;coldSettings.delay=10;coldSettings.feedback=0;cold.setSettings(coldSettings);float coldL=0,coldR=0;for(int i=0;i<=480;++i){coldL=i==0?.4f:0;coldR=0;cold.process(coldL,coldR);}expect(coldL>.2f&&coldR==0,"first chorus impulse survives the initial delay-history boundary");
    StereoChorus feedback;feedback.prepare(48000);auto p=defaults;p.enabled=true;p.mix=1;p.depth=0;p.delay=10;p.feedback=.5f;feedback.setSettings(p);float l=0,rr=0;for(int i=0;i<16000;++i){l=rr=0;feedback.process(l,rr);}bool echoes=true;for(int i=0;i<=1440;++i){l=i==0?.4f:0;rr=0;feedback.process(l,rr);double expected=i==480?.4:i==960?.2:i==1440?.1:0;echoes&=std::abs(l-expected)<.000002&&rr==0;}expect(echoes,"chorus feedback produces expected decaying echoes without channel leakage");
    for(float width:{0.f,1.f}){StereoChorus fx;fx.prepare(48000);p=custom;p.width=width;fx.setSettings(p);double difference=0;bool finite=true;for(int i=0;i<24000;++i){l=rr=.2f*std::sin(i*.057);fx.process(l,rr);difference+=std::abs(l-rr);finite&=std::isfinite(l)&&std::isfinite(rr);}expect(finite&&(width==0?difference==0:difference>1),"width zero preserves mono and full width creates stereo modulation");}
    for(double rate:{8000.,48000.,192000.})for(float fb:{-.8f,.8f}){StereoChorus fx;fx.prepare(rate);p=defaults;p.enabled=true;p.mix=1;p.depth=1;p.delay=5;p.rate=8;p.feedback=fb;fx.setSettings(p);bool stable=true;for(int i=0;i<48000;++i){l=.2f*std::sin(i*.13);rr=-l;fx.process(l,rr);stable&=std::isfinite(l)&&std::isfinite(rr)&&std::abs(l)<1.01f&&std::abs(rr)<1.01f;}expect(stable,"extreme chorus rate/depth/feedback stays bounded at supported sample rates");}
    StereoChorus bypass;bypass.prepare(48000);bool exact=true;for(int i=0;i<2000;++i){l=.19f*std::sin(i*.1f);rr=-l;float a=l,b=rr;bypass.process(l,rr);exact&=a==l&&b==rr;}expect(exact,"bypassed chorus is bit-exact and introduces no dry latency");
    p=custom;p.mix=0;bypass.setSettings(p);exact=true;for(int i=0;i<2000;++i){l=.13f*std::sin(i*.3f);rr=-l;float a=l,b=rr;bypass.process(l,rr);exact&=a==l&&b==rr;}expect(exact,"enabled zero-mix chorus preserves both input channels exactly");
    p=custom;bypass.setSettings(p);for(int i=0;i<24000;++i){l=rr=.1f;bypass.process(l,rr);}p.enabled=false;bypass.setSettings(p);for(int i=0;i<24000;++i){l=rr=0;bypass.process(l,rr);}l=.23f;rr=-.17f;bypass.process(l,rr);expect(l==.23f&&rr==-.17f,"bypass fades to exact dry and does not retain old feedback");bypass.reset();p.enabled=true;bypass.setSettings(p);bool silent=true;for(int i=0;i<6000;++i){l=rr=0;bypass.process(l,rr);silent&=l==0&&rr==0;}expect(silent,"Stop/reset invalidates delay history without stale echoes on restart");
    auto song=emptyProject();song.masterSoftClip=true;song.bpm=120;song.loop=false;song.patterns[0].length=4;song.patterns[0].lanes[7]={{0,1,60,.8f},{1,1,67,.7f}};song.tracks[7].send=0;auto dry=render(song,assets,root,72000,127);song.tracks[7].mixer.chorus=custom;auto wet=render(song,assets,root,72000,127),blocks=render(song,assets,root,72000,512);bool same=true;double difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<72000;++i){same&=wet.getSample(ch,i)==blocks.getSample(ch,i);difference+=std::abs(wet.getSample(ch,i)-dry.getSample(ch,i));}expect(same&&difference>1&&wet.getMagnitude(0,0,72000)>.001f,"integrated chorus is audible and independent of callback size");
    auto file=root.getChildFile("chorus-project.pulse");Project restored;expect(saveProject(song,file).wasOk()&&loadProject(file,restored).wasOk()&&restored.tracks[7].mixer.chorus==custom&&restored.patterns[0].length==4,"schema 9 saves complete chorus state and variable pattern length");
    auto json=projectToJson(song);json.getDynamicObject()->setProperty("schema",8);for(auto& row:*json["tracks"].getArray())row["mixer"].getDynamicObject()->removeProperty("chorus");expect(projectFromJson(json,restored).wasOk()&&restored.tracks[7].mixer.chorus==defaults,"schema 8 migrates with a bypassed chorus");auto legacy=render(restored,assets,root,72000,127);same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<72000;++i)same&=legacy.getSample(ch,i)==dry.getSample(ch,i);expect(same,"legacy migration preserves exact original audio");
    auto broken=projectToJson(song);(*broken["tracks"].getArray())[7]["mixer"].getDynamicObject()->removeProperty("chorus");auto before=JSON::toString(projectToJson(restored));expect(projectFromJson(broken,restored).failed()&&JSON::toString(projectToJson(restored))==before,"new schema cannot silently discard missing chorus data");
    auto hash=SHA256(file).toHexString();song.tracks[7].mixer.chorus.rate=std::numeric_limits<float>::quiet_NaN();expect(saveProject(song,file).failed()&&SHA256(file).toHexString()==hash,"invalid chorus cannot replace a valid project file");String warnings;auto playback=std::make_unique<Playback>();expect(compilePlayback(song,assets,root,*playback,warnings).failed(),"invalid chorus cannot enter callback snapshot");
    song.tracks[7].mixer.chorus=custom;auto bus=song;bus.tracks[5].isBus=true;bus.tracks[5].cutoff=20000;bus.tracks[5].volume=1;bus.tracks[7].mixer.chorus.enabled=false;bus.tracks[7].mixer.output=5;bus.tracks[5].mixer.chorus=custom;auto busWet=render(bus,assets,root,48000);bus.tracks[5].mixer.chorus.enabled=false;auto busDry=render(bus,assets,root,48000);difference=0;for(int i=0;i<48000;++i)difference+=std::abs(busWet.getSample(0,i)-busDry.getSample(0,i));expect(difference>1,"chorus processes routed mixer buses as well as source channels");
    auto engine=makeEngine(song,assets,root);AudioBuffer<float> block(2,512);for(int i=0;i<30;++i)engine->render(block.getWritePointer(0),block.getWritePointer(1),512);engine->stop();engine->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(block.getMagnitude(0,0,512)==0,"engine Stop clears chorus feedback and voices");
    RenderSettings encoding;encoding.bits=32;encoding.tailSeconds=0;encoding.endBeat=3;auto exportFile=root.getChildFile("chorus-export.wav");expect(renderAudio(song,assets,root,exportFile,encoding).wasOk(),"offline WAV export includes chorus");String decodeError;auto* exported=assets.load(exportFile,decodeError);same=exported&&exported->audio.getNumSamples()==72000;if(same)for(int ch=0;ch<2;++ch)for(int i=0;i<72000;++i)same&=std::abs(exported->audio.getSample(ch,i)-wet.getSample(ch,i))<.000001f;expect(same,"float WAV export matches callback chorus audio sample for sample");
    auto templateRoot=root.getChildFile("chorus-templates");ProjectTemplate info;expect(saveProjectTemplate(song,root,templateRoot,"Chorus template","Stereo",TemplateContent::complete,info).wasOk(),"chorus project can be saved as a local template");Project fromTemplate;expect(loadProjectTemplate(info,fromTemplate).wasOk()&&fromTemplate.tracks[7].mixer.chorus==custom,"personal template retains chorus controls independently");
}
